// Parse AI Agent JSON response, normalize fields, and attach source metadata
const out = [];

function toNumberOrNull(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : null;
}

function deriveId(listing) {
  if (!listing) return null;
  if (listing.id != null && String(listing.id).trim() !== '') return String(listing.id).trim();

  const url = listing.url || listing.link;
  if (typeof url === 'string') {
    const m = url.match(/\/([0-9]{5,})\/?(?:\?|#|$)/);
    if (m) return m[1];
  }
  return null;
}

for (const item of $input.all()) {
  const sourceUrl = item.json.source_url;
  const scrapeError = item.json.scrape_error;

  const aiText =
    item.json.output?.output || // handles double-wrapped cases
    item.json.output ||         // common AI Agent output
    item.json.response ||
    item.json.message ||
    item.json.text ||
    '';

  if (scrapeError) {
    out.push({ json: { source_url: sourceUrl, currency: null, listings: [], error: scrapeError } });
    continue;
  }

  try {
    let cleaned = (aiText || '').trim();
    cleaned = cleaned.replace(/```json\s*/gi, '').replace(/```/g, '').trim();

    const parsed = JSON.parse(cleaned);
    const currency = parsed.currency ?? null;
    const listings = Array.isArray(parsed.listings) ? parsed.listings : [];

    const normalized = listings
      .map(l => {
        const url = l?.url || l?.link || null;

        return {
          id: deriveId(l),
          title: l?.title ?? null,
          address: l?.address ?? null,
          price: toNumberOrNull(l?.price),
          property_type: l?.property_type ?? null,
          bedrooms: toNumberOrNull(l?.bedrooms),
          bathrooms: toNumberOrNull(l?.bathrooms),
          size_sqm: toNumberOrNull(l?.size_sqm),
          agent: l?.agent ?? null,
          status: l?.status ?? null,
          url,
          notes: l?.notes ?? null,
          source_url: sourceUrl,
        };
      })
      // Keep if it has at least a URL, or a title+price, etc.
      .filter(l => l && (l.url || l.title || l.address));

    out.push({
      json: {
        source_url: sourceUrl,
        currency,
        listings: normalized,
        error: null,
      },
    });

  } catch (e) {
    out.push({
      json: {
        source_url: sourceUrl,
        currency: null,
        listings: [],
        error: `Failed to parse AI output: ${e.message}`,
      },
    });
  }
}

return out;

// Aggregate listings across all inputs, de-duplicate, detect *new* listings, and persist state.
//
// Uses workflow static data (global) to remember which listings were already emailed.
// Each listing is keyed by (id || url || title|address|price).
//
// Output is compatible with downstream IF + Build HTML Email nodes.

const cfg = $('Configuration').first().json;
const runTimestamp = cfg.RUN_TIMESTAMP || new Date().toISOString();

const allListings = [];
const failedSources = [];
let currency = null;
const sourcesChecked = new Set();

function keyOf(l) {
  if (!l) return null;
  if (l.id) return `id:${String(l.id)}`;
  if (l.url) return `url:${String(l.url)}`;
  const t = (l.title || '').trim();
  const a = (l.address || '').trim();
  const p = (l.price != null) ? String(l.price) : '';
  const key = [t, a, p].filter(Boolean).join('|');
  return key ? `meta:${key.toLowerCase()}` : null;
}

// Collect everything from incoming items
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.source_url) sourcesChecked.add(j.source_url);

  if (j.error) {
    failedSources.push({
      url: j.source_url || 'unknown',
      error: j.error,
    });
  }

  if (!currency && j.currency) {
    currency = j.currency;
  }

  if (Array.isArray(j.listings) && j.listings.length > 0) {
    allListings.push(...j.listings);
  }
}

// De-duplicate. If duplicates exist, prefer one that has a price.
const byKey = new Map();
for (const l of allListings) {
  const k = keyOf(l);
  if (!k) continue;

  if (!byKey.has(k)) {
    byKey.set(k, l);
    continue;
  }

  const existing = byKey.get(k);
  const existingHasPrice = existing?.price != null && Number.isFinite(Number(existing.price));
  const currentHasPrice = l?.price != null && Number.isFinite(Number(l.price));

  if (!existingHasPrice && currentHasPrice) {
    byKey.set(k, l);
  }
}

const deduped = Array.from(byKey.values());

// Sort by price (ascending), nulls last
deduped.sort((a, b) => {
  const ap = (a?.price != null && Number.isFinite(Number(a.price))) ? Number(a.price) : Infinity;
  const bp = (b?.price != null && Number.isFinite(Number(b.price))) ? Number(b.price) : Infinity;
  return ap - bp;
});

// --- Detect new listings (persist across runs) ---
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenDaftListings) staticData.seenDaftListings = {};
if (!staticData.seenDaftListingsOrder) staticData.seenDaftListingsOrder = [];

const seen = staticData.seenDaftListings;
const order = staticData.seenDaftListingsOrder;

const newListings = [];
for (const l of deduped) {
  const k = keyOf(l);
  if (!k) continue;
  if (!seen[k]) {
    newListings.push(l);
    seen[k] = runTimestamp;
    order.push(k);
  }
}

// Prevent unbounded growth
