            <th style="text-align:left;padding:10px;">Listing</th>
          </tr>
        </thead>
        <tbody>
          ${rows || `<tr><td colspan="2" style="padding:12px;">No new listings.</td></tr>`}
        </tbody>
      </table>
    </div>

    <div style="margin-top:22px;">
      <h3 style="margin:0 0 8px 0;">Search links</h3>
      <ul style="margin:0 0 0 18px;">${searchLinks}</ul>
    </div>

    ${failedSection}

    <p style="margin-top:28px;color:#777;font-size:12px;">Automated report generated by n8n using Firecrawl + Gemini.</p>
  </div>
</body>
</html>
`;

const subjectDate = new Date(runTime).toLocaleDateString('en-IE');
const emailSubject = `${cfg.EMAIL_SUBJECT_PREFIX} ${newListings.length} new listing(s) - ${subjectDate}`;

return [{
  json: {
    html_email: html,
    email_subject: emailSubject,
    email_to: cfg.EMAIL_TO
  }
}];
